CREATE TABLE tutor_sessions (id varchar(64) PRIMARY KEY, account_id varchar(64) NOT NULL, course_id varchar(64), target_concept_id varchar(128), subject_domain varchar(80) NOT NULL, high_stakes boolean NOT NULL, state varchar(24) NOT NULL CHECK(state IN ('active','paused','closed')), hint_level integer NOT NULL CHECK(hint_level>=0), turn_count integer NOT NULL CHECK(turn_count>=0), row_version integer NOT NULL CHECK(row_version>0), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX ix_tutor_session_account ON tutor_sessions(account_id,state,updated_at);
CREATE TABLE tutor_turns (id varchar(64) PRIMARY KEY, session_id varchar(64) NOT NULL REFERENCES tutor_sessions(id), account_id varchar(64) NOT NULL, question text NOT NULL, move varchar(24) NOT NULL, reason varchar(128) NOT NULL, target_concept_id varchar(128), bloom_target varchar(24) NOT NULL, hint_level integer NOT NULL, requires_sources boolean NOT NULL, next_action varchar(128) NOT NULL, evidence text NOT NULL, created_at timestamptz NOT NULL, mutation_id varchar(96));
CREATE INDEX ix_tutor_turn_session ON tutor_turns(account_id,session_id,created_at);
CREATE UNIQUE INDEX uq_tutor_turn_mutation ON tutor_turns(account_id,mutation_id) WHERE mutation_id IS NOT NULL;
